const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',book:'<path d="M12 5v16M3 4h5a4 4 0 0 1 4 3 4 4 0 0 1 4-3h5v15h-5a4 4 0 0 0-4 2 4 4 0 0 0-4-2H3z"/>',cards:'<rect x="7" y="3" width="13" height="16" rx="2"/><path d="M4 7H3v14h13v-1M11 8h5m-5 4h5"/>',plan:'<path d="M8 5h13M8 12h13M8 19h13m-19-15 1 1 2-2m-3 8 1 1 2-2m-3 8 1 1 2-2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2m-8 3h2"/>',notes:'<path d="M14 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-9M9 15l2-5 8-8 3 3-8 8z"/>',link:'<path d="M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',flame:'<path d="M12 3c1 4 5 6 5 11a5 5 0 0 1-10 0c0-3 2-4 2-7 2 1 3 3 3 5 1-2 1-5 0-9z"/>',bolt:'<path d="M13 2 4 14h7l-1 8 9-12h-7z"/>',bulb:'<path d="M9 18h6m-5 3h4M12 3a6 6 0 0 0-4 10.5c.8.8 1 1.5 1 2.5h6c0-1 .2-1.7 1-2.5A6 6 0 0 0 12 3z"/>',star:'<path d="m12 3 2.7 5.6 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1-4.4-4.3 6.1-.9z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',gear:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.8-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.8.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.8 1.7 1.7 0 0 0-1.5-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.5-1.1 1.7 1.7 0 0 0-.3-1.8l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.8.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.8-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.8V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1z"/>',alert:'<path d="M12 9v4m0 4h.01M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/>',spark:'<path d="M12 3v4m0 10v4M3 12h4m10 0h4M6 6l2.5 2.5m7 7L18 18M6 18l2.5-2.5m7-7L18 6"/>',quote:'<path d="M7 7h4v4c0 3-1.5 5-4 6m6-10h4v4c0 3-1.5 5-4 6"/>'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error('unavailable')},setItem(){throw Error('unavailable')}};}
const loaded=loadState(storage);let state=loaded.state;let locked=!!loaded.error;
let currentView='home',currentId='',prepMode='practice',reviewMode='cards',reviewCourse='',mistakesOnly=false,includeUnread=false,quizIndex=0,flipped=false,searchQuery='',reviewQueue=null;
const main=document.querySelector('#main');
let studySpace;
const navItems=[['home','home','พื้นที่เรียนของฉัน','หน้าหลัก'],['courses','book','ติวก่อนเรียน','ติว'],['classroom','book','เนื้อหาจากห้องเรียน','ห้องเรียน'],['review','cards','ทบทวนเนื้อหาติว','ทบทวน'],['plan','plan','แผนการเรียน','แผน'],['calendar','calendar','ปฏิทินเรียนและสอบ','ปฏิทิน'],['exams','target','ตารางสอบ & แนวข้อสอบ','สอบ'],['resources','link','ศูนย์การเรียนออนไลน์','แหล่งเรียน'],['notes','notes','สมุดจดของฉัน','สมุดจด'],['account','gear','ข้อมูลและเปิดบนอีกเครื่อง','ข้อมูล']];
let toastTimer;
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function storageWarning(message){const el=document.querySelector('#storage-warning');el.hidden=!message;el.textContent=message||'';}
if(loaded.error)storageWarning(loaded.error);
if(contentStatus.warning){const el=document.querySelector('#content-warning');el.hidden=false;el.textContent=contentStatus.warning;}
function save(){try{const ok=studySpace.saveProgress(state);storageWarning(studySpace.info().cacheWarning);return ok;}catch(err){storageWarning(err.message);return false;}}
const link=(hash,text,cls='button primary')=>`<a class="${cls}" href="#${hash}">${text}</a>`;
const badge=(txt,cls='')=>`<span class="badge ${cls}">${e(txt)}</span>`;
const courseById=id=>courses.find(c=>c.id===id);
const lessonById=id=>lessons.find(l=>l.id===id);
const colorOf=id=>courseColors[Math.max(0,courses.findIndex(v=>v.id===id))%courseColors.length];
const loadLabel={'หนัก':'เนื้อหาหนัก','กลาง':'ปานกลาง','เบากว่า':'อ่านคล่อง'};
function heading(kicker,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${action}</div>`;}
function smallProgress(p){return `<div class="progress-label"><span>ติวแล้ว ${p.done} / ${p.total} บท</span><b>${p.percent}%</b></div><div class="progress-track" role="progressbar" aria-valuenow="${p.percent}" aria-valuemin="0" aria-valuemax="100" aria-label="ความคืบหน้าติวก่อนเรียน"><span style="width:${p.percent}%"></span></div>`;}
function greeting(){const h=Number(new Intl.DateTimeFormat('en-GB',{hour:'numeric',hourCycle:'h23',timeZone:'Asia/Bangkok'}).format(new Date()));return h<5?'ดึกแล้ว พักบ้างนะ':h<12?'สวัสดีตอนเช้า':h<17?'สวัสดีตอนบ่าย':'สวัสดีตอนเย็น';}
function card(c){const p=courseProgress(state,c.id);return `<a class="course-card" href="#course/${c.id}" style="--course:${colorOf(c.id)}"><div class="cc-top"><span class="cc-code">${c.id}</span><span class="cc-load">${e(loadLabel[c.load]||c.load)}</span></div><h3>${e(c.title)}</h3><p>${e(c.reason)}</p><div class="cc-exam">${icon('calendar',17)} สอบ ${thaiDate(c.exam,true)} · คาบ ${c.slot}</div>${smallProgress(p)}<div class="cc-go">${p.done?'ติวต่อ':'เริ่มติว'} ${icon('arrow',16)}</div></a>`;}

function blockRow(b,doneIds){const done=doneIds.includes(b.id);return `<li class="block ${done?'is-done':''} ${b.id==='examday'?'is-exam':''}" style="--course:${b.course?colorOf(b.course):'var(--blue)'}"><button type="button" class="block-check" data-action="block" data-id="${b.id}" aria-pressed="${done}" aria-label="${done?'ยกเลิกเครื่องหมาย':'ทำช่วงนี้แล้ว'}: ${e(b.title)}">${icon('check',18)}</button><div class="block-body"><div class="block-top"><span class="block-time">${b.minutes?`${icon('clock',15)} ${b.minutes} นาที`:`${icon('star',15)} วันสอบ`}</span>${b.course?`<span class="chip">${b.course}</span>`:''}${b.href?`<a class="block-go" href="${b.href}" aria-label="เริ่ม: ${e(b.title)}">เริ่ม ${icon('arrow',16)}</a>`:''}</div><h3>${e(b.title)}</h3><p>${e(b.detail)}</p></div></li>`;}
function todayPlanHTML(){
 const day=today(),plan=dailyPlan(state,day),doneIds=state.planDone[day]||[];
 if(!plan.blocks.length)return `<section class="today panel"><div class="today-head"><div><span class="eyebrow">แผนวันนี้</span><h2>สอบครบทั้ง 7 วิชาแล้ว</h2><p>พักให้เต็มที่ แล้วบันทึกผลสอบในหน้าแผนการเรียน</p></div></div>${link('plan','ไปที่แผนการเรียน')}</section>`;
 const pct=Math.round(plan.done/plan.blocks.length*100);
 return `<section class="today panel" aria-labelledby="today-title"><div class="today-head"><div><span class="eyebrow">แผนวันนี้ · ${e(plan.phase.name)}</span><h2 id="today-title">${plan.done===plan.blocks.length?'ครบแผนวันนี้แล้ว เก่งมาก':`เรียน ${plan.minutes>=60?`${Math.round(plan.minutes/6)/10} ชั่วโมง`:`${plan.minutes} นาที`} แบ่งเป็น ${plan.blocks.length} ช่วง`}</h2><p>ทำทีละช่วง กดวงกลมเมื่อทำเสร็จ · พักสายตา 5 นาทีทุกชั่วโมง</p></div><div class="today-ring" style="--p:${pct}%"><b>${plan.done}/${plan.blocks.length}</b><span>ช่วง</span></div></div>
 <div class="hours-picker" role="group" aria-label="วันนี้มีเวลาเรียนกี่ชั่วโมง"><span>วันนี้มีเวลา</span>${studyHours.map(h=>`<button type="button" class="hour-chip ${plan.hours===h?'active':''}" data-action="hours" data-value="${h}" aria-pressed="${plan.hours===h}">${h} ชม.${h===1?' <small>วันยุ่ง</small>':''}</button>`).join('')}</div>
 <ol class="blocks">${plan.blocks.map(b=>blockRow(b,doneIds)).join('')}</ol></section>`;
}
function journeyHTML(day){const current=phaseFor(day);const idx=studyPhases.indexOf(current);return `<section class="journey"><div class="section-heading"><div><h2>เส้นทางถึงวันสอบ</h2><p>แบ่งเป็น 4 ช่วง แผนรายวันจะเปลี่ยนตามช่วงให้อัตโนมัติ</p></div></div><ol class="journey-steps">${studyPhases.map((p,i)=>`<li class="${i<idx?'past':i===idx?'current':''}"><span class="step">${i<idx?icon('check',16):i+1}</span><div><b>${e(p.name)}</b><small>${e(p.range)}</small><p>${e(p.goal)}</p></div></li>`).join('')}</ol></section>`;}
function home(){
 const day=today(),p=progress(state),list=exams(),next=list.find(c=>c.exam>=day),phase=phaseFor(day);
 const due=cardsForReview(state).length,days=next?daysBetween(day,next.exam):0,s=streak(state,day);
 const resume=state.lastLesson&&!state.completed.includes(state.lastLesson)?lessonById(state.lastLesson):null;
 const hrs=next?hoursUntil(state,day,next.exam):0;
 const title={learn:'ติวล่วงหน้าทีละช่วง',review:'ช่วงทบทวน เก็บทีละวิชา',exam:'ช่วงสอบ โฟกัสวิชาถัดไป',done:'สอบครบแล้ว เก่งมาก'}[phase.id];
 return `<div class="welcome"><div><span class="eyebrow">${greeting()} · ${thaiDate(day)}</span><h1>${title}</h1></div></div>
 ${studySections('')}<section class="hero" aria-label="นับถอยหลังวันสอบ"><div class="hero-main"><span class="hero-pill">${icon('target',16)} ช่วงที่ ${studyPhases.indexOf(phase)+1} · ${e(phase.name)}</span>${next?`<div class="countdown">${days?`<b>${days}</b><span>วัน</span>`:'<b class="today-word">วันนี้</b>'}</div><p class="hero-line">${days?'ถึงสอบวิชาถัดไป':'มีสอบ'} <b>${next.id}</b><br>${thaiDate(next.exam,true)} · คาบ ${next.slot}</p>${days?`<div class="hero-meta"><span>${icon('clock',16)} เวลาเรียนตามแผนอีกราว ${hrs} ชม.</span><span>${icon('book',16)} เฉลี่ยวิชาละ ${Math.round(hrs/7)} ชม.</span></div>`:''}`:`<div class="countdown"><b class="today-word">ครบแล้ว</b></div><p class="hero-line">สอบครบทั้ง 7 วิชาของภาค 2/2569</p>`}</div><div class="hero-ring" style="--p:${p.percent}%" role="img" aria-label="อ่านจบ ${p.done} จาก ${p.total} บท"><div><b>${p.done}<small>/${p.total}</small></b><span>บทติวที่อ่านจบ</span></div></div></section>
 <a class="calendar-home-link" href="#calendar"><span>📅</span><div><strong>ปฏิทินเรียนและสอบ</strong><p>วัน เวลา ห้องเรียน และแหล่งอ้างอิงของทั้ง 7 วิชา</p></div><b>เปิดปฏิทิน →</b></a><div class="study-shortcuts"><a href="#resources"><strong>ศูนย์การเรียนส่วนตัว →</strong><span>รวมคำบรรยาย ตำรา และห้องเรียน 7 วิชา</span></a><a href="https://ondemand.ru.ac.th/" target="_blank" rel="noopener noreferrer"><strong>▶ RU on Demand ↗</strong><span>ดูคำบรรยายย้อนหลัง</span></a><a href="http://cyberclassroom.ru.ac.th/" target="_blank" rel="noopener noreferrer"><strong>● Cyber Classroom ↗</strong><span>เรียนสดตามตารางบรรยาย</span></a><a href="https://bookstore.ru.ac.th/" target="_blank" rel="noopener noreferrer"><strong>ร้านหนังสือรามคำแหง ↗</strong><span>ค้นหาและซื้อตำราประจำวิชา</span></a></div><div class="home-grid"><div class="home-main">${todayPlanHTML()}</div><aside class="home-side">
 <div class="stat-card flame"><span class="stat-icon">${icon('flame',22)}</span><div><b>${s} <small>วัน</small></b><span>${s?'เรียนต่อเนื่อง':'ติ๊กแผนวันนี้เพื่อเริ่มนับ'}</span></div></div>
 <a class="stat-card prep-card" href="#exams"><span class="stat-icon">${icon('target',22)}</span><div><b>${Object.values(prep).reduce((n,g)=>n+g.questions.length,0)} <small>ข้อ</small></b><span>แนวข้อสอบ 7 วิชา</span></div>${icon('arrow',16)}</a>
 <a class="stat-card mint" href="#review"><span class="stat-icon">${icon('cards',22)}</span><div><b>${due} <small>ใบ</small></b><span>การ์ดถึงรอบทบทวน</span></div>${icon('arrow',16)}</a>
 ${resume?`<a class="resume" href="#lesson/${resume.id}" style="--course:${colorOf(resume.course)}"><span class="eyebrow">อ่านค้างไว้</span><b>${resume.course} · บทที่ ${resume.n}</b><span>${e(resume.title)}</span><em>อ่านต่อ ${icon('arrow',16)}</em></a>`:''}
 <div class="tip-card"><b>${icon('bulb',18)} เคล็ดลับคนทำงาน</b><p>เปิด “เข้าใจใน 1 นาที” ตอนเดินทางหรือพักเที่ยง แล้วเก็บช่วงอ่านละเอียดไว้ตอนเย็นที่สมาธิดีที่สุด</p></div></aside></div>
 <div class="section-heading"><div><h2>ติวก่อนเรียน · 7 วิชาที่ลงไว้</h2><p>เนื้อหาปูพื้นฐานที่เรียบเรียงขึ้น แยกจากคำบรรยายจริงของอาจารย์</p></div>${link('courses','ดูเนื้อหาติวทั้งหมด →','text-link')}</div>
 <div class="course-grid">${courses.filter(c=>c.enrolled).map(card).join('')}</div>
 ${journeyHTML(day)}
 <p class="quiet-note">${e(meta.scope)} · แบบทบทวนเป็นโจทย์แต่งใหม่ รูปแบบข้อสอบจริงต้องดูประกาศผู้สอน</p>`;
}
function courseLibrary(){return `${heading('PRE-CLASS PREPARATION','ติวก่อนเรียน',`${lessons.length} บทสำหรับปูพื้นฐาน · เรียบเรียงขึ้นเพื่อเตรียมตัวก่อนเข้าห้องเรียน`)}${studySections('prep')}${prepNotice()}<label class="searchbox">${icon('search')}<input id="lesson-search" type="search" placeholder="ค้นหา เช่น ฮอบส์ POSDCORB ความชอบธรรม" value="${e(searchQuery)}" aria-label="ค้นหาเนื้อหาติวก่อนเรียน"></label><div id="library-results">${libraryResults()}</div>`;}
function libraryResults(){if(!searchQuery.trim())return `<div class="course-grid">${courses.filter(c=>c.enrolled).map(card).join('')}</div>`;const q=searchQuery.toLocaleLowerCase();const found=lessons.filter(l=>(l.course+l.title+l.intro+l.sections.map(s=>s.heading+' '+s.body).join(' ')+(l.easy?[l.easy.one,...l.easy.points,l.easy.analogy,l.easy.remember]:[]).join(' ')+l.cards.map(c=>c.front+' '+c.back).join(' ')).toLocaleLowerCase().includes(q));return `<p class="result-count">พบ ${found.length} บทเรียน</p><div class="lesson-list">${found.map(lessonRow).join('')||'<div class="empty">ยังไม่พบหัวข้อนี้ ลองใช้คำสั้นลงหรือค้นด้วยรหัสวิชา</div>'}</div>`;}
function lessonRow(l){const done=state.completed.includes(l.id);return `<a class="lesson-row ${done?'done':''}" href="#lesson/${l.id}" style="--course:${colorOf(l.course)}"><span class="lesson-number">${done?icon('check'):String(l.n).padStart(2,'0')}</span><div><span class="code">${l.course} · บทที่ ${l.n}${l.part===2?' · ภาค 2 เจาะตำรา':''}</span><h3>${e(l.title)}</h3><p>${e(l.easy?.one||l.intro)}</p></div><span class="lesson-duration">${l.minutes} นาที<b>${done?'อ่านจบแล้ว ✓':'เริ่มอ่าน →'}</b></span></a>`;}
function coursePage(id){const c=courseById(id);if(!c||!c.enrolled)return missing();const ls=lessons.filter(l=>l.course===id),p=courseProgress(state,id),left=daysBetween(today(),c.exam);return `${link('courses','← ติวก่อนเรียนทุกวิชา','back-link')}${studySections('prep')}${prepNotice()}<header class="course-hero" style="--course:${colorOf(id)}"><div><span class="cc-code">${c.id}</span><h1>${e(c.title)}</h1><p>${e(c.reason)}</p><div class="course-facts"><span>${icon('calendar',17)} สอบ ${thaiDate(c.exam)} · คาบ ${c.slot}${left>0?` · อีก ${left} วัน`:''}</span><span>${icon('book',17)} ${e(categories[c.category])} · 3 หน่วยกิต</span><span>${icon('target',17)} ${e(loadLabel[c.load]||c.load)}</span></div></div><div class="course-hero-progress">${smallProgress(p)}${link('lesson/'+nextLesson(state,id).id,`${p.done?'ติวบทถัดไป':'เริ่มติวบทแรก'} ${icon('arrow',16)}`,'button white')}</div></header><div class="notice">เนื้อหาติววิชานี้มี ${ls.length} บท: ภาค 1 แนวคิดพื้นฐานพร้อมเจาะลึก และภาค 2 เจาะเนื้อหาตามตำรา ทุกบทเรียบเรียงใหม่และมีแหล่งอ้างอิงท้ายบท ใช้คู่ตำราและคำบรรยายอาจารย์ ขอบเขตและรูปแบบสอบภาค 2/2569 ยังต้องตรวจประกาศผู้สอน</div>${lectureInfo(id)}${courseResources(id)}${partBlock('ภาค 1 · พื้นฐานที่ต้องเข้าใจ','แนวคิดหลักของวิชา อ่านเป็นลำดับแรก แต่ละบทมีส่วนเจาะลึกต่อท้าย',ls.filter(l=>l.part!==2))}${partBlock('ภาค 2 · เจาะเนื้อหาตามตำรา','หัวข้อตามสารบัญตำราและเรื่องที่ข้อสอบมักถาม เขียนแบบจัดเต็มพร้อมตารางสรุป',ls.filter(l=>l.part===2))}${prepStrip(id)}<div class="resource-strip"><div><h3>เรียนคู่กับคำบรรยายมหาวิทยาลัย</h3><p>ค้นรหัส ${c.id} แล้วเลือกภาคเรียนให้ตรง หากใช้วิดีโอภาคเก่าให้ตรวจขอบเขตกับอาจารย์อีกครั้ง</p></div><a class="button secondary" href="https://ondemand.ru.ac.th/" target="_blank" rel="noopener noreferrer">เปิด RU on Demand ↗</a></div>`;}
function partBlock(title,sub,list){return list.length?`<div class="part-head"><h2>${title}</h2><p>${sub}</p></div><div class="lesson-list">${list.map(lessonRow).join('')}</div>`:'';}
function bodyHTML(text){return String(text).split(/\n\s*\n/).map(p=>p.trim()).filter(Boolean).map(p=>`<p>${e(p)}</p>`).join('');}
function tableHTML(t){return `<div class="table-scroll sec-table"><table><thead><tr>${t.head.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(r=>`<tr>${r.map((c,j)=>`<td data-label="${e(t.head[j])}">${e(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function sectionHTML(s,i){return `<section id="section-${i}" class="reading-section"><span class="section-num">${i+1}</span><div><h2>${e(s.heading)}</h2>${bodyHTML(s.body)}${s.list?`<ul class="sec-list">${s.list.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:''}${s.table?tableHTML(s.table):''}</div></section>`;}
function sectionsHTML(l){const firstDeep=l.sections.findIndex(s=>s.deep);return l.sections.map((s,i)=>`${i===firstDeep?`<div class="part-title deep"><span>${icon('target',16)} เจาะลึก</span></div>`:''}${sectionHTML(s,i)}`).join('');}
function refsHTML(l){if(!l.refs?.length)return '';return `<section class="refs" id="section-refs"><h2>แหล่งอ้างอิงและอ่านต่อ</h2><ol>${l.refs.map(r=>`<li><b>${r.url?`<a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">${e(r.title)} ↗</a>`:e(r.title)}</b><span>${e(r.detail)}</span></li>`).join('')}</ol><p class="quiet-note">เนื้อหาบทนี้เรียบเรียงใหม่โดยอาศัยแหล่งข้างต้นและความรู้พื้นฐานในสาขา ลิงก์ตรวจจากผลค้นหา ณ ต.ค. 2569 ให้เทียบกับตำราฉบับที่ใช้ภาคนี้เสมอ</p></section>`;}
function nextHTML(l,next){if(next)return `<a class="next-card" href="#lesson/${next.id}" style="--course:${colorOf(next.course)}"><span class="eyebrow">บทถัดไป · บทที่ ${next.n}</span><b>${e(next.title)}</b>${l.teaser?`<p>${e(l.teaser)}</p>`:''}<em>อ่านต่อ ${icon('arrow',16)}</em></a>`;return `<a class="next-card" href="#prep/${l.course}" style="--course:${colorOf(l.course)}"><span class="eyebrow">จบทุกบทของวิชานี้แล้ว</span><b>ลองทำแนวข้อสอบ ${l.course}</b><p>${e(l.teaser||'วัดความเข้าใจด้วยข้อสอบเสมือนแบบ 5 ตัวเลือก แล้วกลับมาอ่านบทที่ยังตอบผิด')}</p><em>ไปที่แนวข้อสอบ ${icon('arrow',16)}</em></a>`;}
function questionHTML(q,id,index,context='lesson'){const key=`${id}:${index}`,chosen=state.answers[key],answered=Number.isInteger(chosen);return `<div class="question-block"><div class="eyebrow">${context==='lesson'?`คำถามที่ ${index+1}`:'ฝึกตอบทีละข้อ'}</div><h3>${e(q.prompt)}</h3><div class="choices">${q.options.map((o,i)=>`<button type="button" class="choice ${answered&&i===q.answer?'correct':''} ${answered&&i===chosen&&chosen!==q.answer?'incorrect':''}" data-action="answer" data-lesson="${id}" data-index="${index}" data-value="${i}" aria-pressed="${chosen===i}" ${answered?'disabled':''}><span>${'กขคง'[i]}</span>${e(o)}${answered&&i===q.answer?'<b>✓</b>':''}</button>`).join('')}</div>${answered?`<div class="answer-explanation ${chosen===q.answer?'correct':'incorrect'}"><strong>${chosen===q.answer?'ถูกต้อง':'ลองทบทวนแนวคิดอีกนิด'}</strong><p>${e(q.explanation)}</p></div>`:''}</div>`;}
function quickHTML(l){const x=l.easy;if(!x)return '';return `<section id="section-quick" class="quick" aria-labelledby="quick-title"><div class="quick-head">${icon('bolt',18)}<span id="quick-title">เข้าใจใน 1 นาที</span></div><p class="quick-one">${e(x.one)}</p><ol class="key-points">${x.points.map(t=>`<li>${e(t)}</li>`).join('')}</ol><div class="analogy"><b>${icon('bulb',18)} เปรียบเทียบให้เห็นภาพ</b><p>${e(x.analogy)}</p></div><div class="memory"><b>${icon('star',17)} จำง่าย ๆ</b><p>${e(x.remember)}</p></div></section>`;}
function lessonPage(id){const l=lessonById(id);if(!l)return missing();const c=courseById(l.course),ls=lessons.filter(v=>v.course===l.course),next=ls.find(v=>v.n===l.n+1),done=state.completed.includes(id);return `${link('course/'+l.course,'← '+l.course+' · ดูบทติวทั้งหมด','back-link')}${prepNotice()}
 <header class="lesson-hero" style="--course:${colorOf(l.course)}"><div class="lesson-hero-top"><span class="cc-code">${l.course}</span><span>บทที่ ${l.n} / ${ls.length} · ${l.part===2?'ภาค 2 เจาะตำรา':'ภาค 1 พื้นฐาน'} · ประมาณ ${l.minutes} นาที</span><button class="font-toggle" data-action="font">${state.font==='large'?'ก ลดตัวอักษร':'ก+ ขยายตัวอักษร'}</button></div><h1>${e(l.title)}</h1><p>${e(c.title)} · ${e(l.intro)}</p><div class="lesson-dots" aria-label="บทในวิชานี้">${ls.map(v=>`<a href="#lesson/${v.id}" class="${v.id===id?'here':''} ${state.completed.includes(v.id)?'read':''}" aria-label="บทที่ ${v.n}${state.completed.includes(v.id)?' อ่านจบแล้ว':''}">${v.n}</a>`).join('')}</div></header>
 <div class="reader-layout"><article class="reading-article">${l.hook?`<section class="hook" id="section-hook"><span class="hook-label">${icon('spark',16)} เปิดเรื่อง</span><p>${e(l.hook)}</p></section>`:''}${quickHTML(l)}<div class="part-title"><span>อ่านละเอียด</span></div>${sectionsHTML(l)}
 <section class="worked-example"><div class="eyebrow">ลองใช้แนวคิด</div><h2>จากสถานการณ์สู่การวิเคราะห์</h2><p>${e(l.example.situation)}</p><div class="analysis-box"><strong>วิธีมองเรื่องนี้</strong><p>${e(l.example.analysis)}</p></div></section><div class="trap"><strong>${icon('alert',18)} จุดที่มักสับสน</strong><p>${e(l.trap)}</p></div>
 <section class="recap" id="section-terms"><h2>คำสำคัญและชื่อที่ควรจำ</h2><p class="recap-note">คำเหล่านี้จะเข้าแฟลชการ์ดให้ทบทวนตามรอบ หลังกด “อ่านจบ”</p><div class="term-grid">${l.cards.map(c=>`<div class="term"><b>${e(c.front)}</b><p>${e(c.back)}</p></div>`).join('')}</div></section>
 <section class="lesson-quiz" id="section-quiz"><div class="section-heading"><div><h2>ลองตอบโดยไม่เปิดย้อน</h2><p>โจทย์แต่งใหม่เพื่อเช็กความเข้าใจ</p></div><button class="text-button" data-action="retry" data-id="${id}">ลองใหม่</button></div>${l.questions.map((q,i)=>questionHTML(q,id,i)).join('')}</section>
 ${refsHTML(l)}<div class="reflection"><strong>อธิบายให้ตัวเองฟัง</strong><p>${e(l.reflection)}</p></div>
 <div class="lesson-finish"><button class="button ${done?'secondary':'primary'}" data-action="complete" data-id="${id}">${icon('check')} ${done?'อ่านจบแล้ว · ยกเลิกเครื่องหมาย':'ทำเครื่องหมายว่าอ่านจบ'}</button>${link('review','ทบทวนด้วยแฟลชการ์ด →','button secondary')}</div>${nextHTML(l,next)}<p class="quiet-note">เรียบเรียงใหม่ ต.ค. 2569 · ไม่ใช่คำบรรยายของอาจารย์หรือขอบเขตข้อสอบทางการ · <a href="#about">แหล่งเรียนรู้</a></p></article>
 <aside class="reading-side"><div class="sticky-side"><div class="panel"><span class="eyebrow">ในบทนี้</span><ol class="toc">${l.easy?'<li><button data-action="section" data-index="quick">เข้าใจใน 1 นาที</button></li>':''}${l.sections.map((s,i)=>`<li><button data-action="section" data-index="${i}">${e(s.heading)}</button></li>`).join('')}<li><button data-action="section" data-index="terms">คำสำคัญและชื่อที่ควรจำ</button></li><li><button data-action="section" data-index="quiz">คำถามทบทวน</button></li>${l.refs?.length?'<li><button data-action="section" data-index="refs">แหล่งอ้างอิงและอ่านต่อ</button></li>':''}</ol></div><div class="panel note-panel"><h3>${icon('notes')} บันทึกของฉัน</h3><button class="button secondary" data-action="nb-from-lesson" data-lesson="${id}">ไฮไลต์ / แทรกรูปในสมุดจด →</button><p>เขียนสิ่งที่เข้าใจ หรือคำถามที่จะกลับมาค้น</p><label class="sr-only" for="lesson-note">บันทึกบท ${e(l.title)}</label><textarea id="lesson-note" data-lesson="${id}" maxlength="50000" placeholder="ลองสรุปด้วยภาษาของตัวเอง…">${e(state.notes[id]||'')}</textarea><span id="note-status" class="save-status" role="status">บันทึกโน้ตใน Supabase อัตโนมัติ</span></div></div></aside></div>`;}
function review(){const due=cardsForReview(state,reviewCourse,today(),includeUnread);if(reviewQueue===null)reviewQueue=quizItems(state,reviewCourse,mistakesOnly);const qs=reviewQueue;return `${heading('PRE-CLASS REVIEW','ทบทวนเนื้อหาติว','แฟลชการ์ดและโจทย์จากเนื้อหาติวก่อนเรียน · โน้ตของคุณทบทวนได้แยกในเมนูสมุดจด')}<div class="review-toolbar"><div class="segmented"><button data-action="mode" data-mode="cards" class="${reviewMode==='cards'?'active':''}">แฟลชการ์ด</button><button data-action="mode" data-mode="quiz" class="${reviewMode==='quiz'?'active':''}">คำถามทบทวน</button></div><label class="select-wrap">วิชา<select id="review-course"><option value="">ทุกวิชา</option>${courses.filter(c=>c.enrolled).map(c=>`<option value="${c.id}" ${reviewCourse===c.id?'selected':''}>${c.id}</option>`).join('')}</select></label></div>${reviewMode==='cards'?flashcardHTML(due):quizHTML(qs)}<p class="quiet-note">การทบทวนไม่ใช่ผลสอบมหาวิทยาลัย · คะแนนในแอปใช้ดูความเข้าใจเท่านั้น</p>`;}
function flashcardHTML(due){const toggle=`<label class="check-label"><input type="checkbox" id="include-unread" ${includeUnread?'checked':''}> รวมการ์ดของบทที่ยังไม่ได้กดอ่านจบ</label>`;if(!due.length)return `${toggle}<div class="empty panel"><span class="empty-symbol">${icon('check',28)}</span><h2>${state.completed.length||includeUnread?'ทบทวนครบสำหรับวันนี้แล้ว':'อ่านจบบทแรก แล้วการ์ดจะมารอที่นี่'}</h2><p>${state.completed.length||includeUnread?'บัตรที่ตอบแล้วจะกลับมาตามรอบ 1, 3 หรือ 7 วัน':'การ์ดของแต่ละบทเข้าคิวทบทวนหลังกด “ทำเครื่องหมายว่าอ่านจบ” หรือเลือกรวมการ์ดทั้งหมดด้านบน'}</p>${link('courses','กลับไปเรียนบทอื่น')}</div>`;const c=due[0];return `${toggle}<div class="review-counter">พร้อมทบทวน ${due.length} ใบ <span>ตอบแล้วจะนัดทบทวนให้ในรอบถัดไป</span></div><div class="flashcard ${flipped?'flipped':''}" style="--course:${colorOf(c.course)}"><span class="cc-code">${c.course}</span><span class="eyebrow">${flipped?'คำอธิบาย':'ลองนึกความหมาย'}</span><h2>${e(flipped?c.back:c.front)}</h2><p>${e(c.title)}</p><button class="button ${flipped?'secondary':'primary'}" data-action="flip">${flipped?'กลับไปดูคำถาม':'เปิดคำอธิบาย'}</button></div>${flipped?`<div class="review-actions"><button class="button secondary" data-action="remember" data-id="${c.id}" data-value="no">ยังไม่แม่น · พรุ่งนี้</button><button class="button primary" data-action="remember" data-id="${c.id}" data-value="yes">จำได้แล้ว ${icon('check')}</button></div>`:'<p class="center muted">ลองตอบออกเสียงสั้น ๆ ก่อนเปิดการ์ด</p>'}${link('lesson/'+c.lesson,'กลับไปอ่านบทนี้ →','center text-link')}`;}
function quizHTML(qs){if(quizIndex>=qs.length)quizIndex=0;const q=qs[quizIndex];return `<label class="check-label"><input type="checkbox" id="mistakes-only" ${mistakesOnly?'checked':''}> เฉพาะข้อที่เคยตอบผิด</label>${!q?`<div class="empty panel"><h2>${mistakesOnly?'ยังไม่มีข้อที่ตอบผิด':'ยังไม่มีคำถาม'}</h2><p>เปลี่ยนตัวกรองเพื่อฝึกข้ออื่นได้</p></div>`:`<div class="quiz-shell panel" style="--course:${colorOf(q.course)}"><div class="review-counter">ข้อ ${quizIndex+1} / ${qs.length} <span>${q.course} · ${e(q.title)}</span></div>${questionHTML(q,q.lesson,q.index,'review')}<div class="review-actions"><button class="button secondary" data-action="quiz-prev" ${quizIndex===0?'disabled':''}>← ก่อนหน้า</button><a href="#lesson/${q.lesson}" class="text-link">อ่านบทที่เกี่ยวข้อง</a><button class="button primary" data-action="quiz-next">${quizIndex+1===qs.length?'กลับไปข้อแรก':'ข้อถัดไป →'}</button></div><button class="text-button" data-action="retry-one" data-id="${q.id}">ตอบข้อนี้ใหม่</button></div>`}`;}
function hourTemplate(){return [['1 ชม.','วันยุ่ง','การ์ด 10 นาที → วิชาหลัก 40 นาที → ปิดท้าย 10 นาที'],['2 ชม.','พื้นฐาน','การ์ด 15 → วิชาหลัก 60 → วิชารอง 30 → ปิดท้าย 15 นาที'],['3 ชม.','เพิ่มคำบรรยาย','แบบ 2 ชม. + ฟังคำบรรยาย RU on Demand วิชาหลัก 60 นาที'],['4 ชม.','วันหยุด','แบบ 3 ชม. + วิชาที่คืบหน้าน้อยที่สุด 60 นาที']];}
function plan(){const s=planSummary(state),day=today();return `${heading('LEARNING ROADMAP','แผนการเรียนของฉัน','เทอมนี้เรียนวันละ 1–4 ชั่วโมงตามเวลาที่มี · ภาพรวมทั้งหลักสูตรอยู่ด้านล่าง')}
 <section class="panel hours-panel"><div><h2>เวลาเรียนของฉัน</h2><p>แผนวันนี้ในหน้าหลักจะแบ่งช่วงตามจำนวนชั่วโมงนี้ เปลี่ยนเฉพาะวันนี้ได้ที่หน้าหลัก</p></div><div class="hours-fields"><label class="field">วันทำงาน (จ.–ศ.)<select id="hours-weekday">${studyHours.map(h=>`<option value="${h}" ${state.hours.weekday===h?'selected':''}>${h} ชั่วโมง</option>`).join('')}</select></label><label class="field">วันหยุด (ส.–อา.)<select id="hours-weekend">${studyHours.map(h=>`<option value="${h}" ${state.hours.weekend===h?'selected':''}>${h} ชั่วโมง</option>`).join('')}</select></label></div><ul class="hour-templates">${hourTemplate().map(([h,label,text])=>`<li><b>${h}</b><span>${label}</span><p>${text}</p></li>`).join('')}</ul></section>
 <div class="section-heading"><div><h2>วิชาประจำวันในช่วงเรียนเนื้อหา</h2><p>วิชาหนักได้วันหลัก 2 วัน · หลัง 1 ก.พ. แผนจะวนตามลำดับวันสอบแทน</p></div></div><div class="week-grid">${readingWeek.map(([dayName,primary,secondary],i)=>`<div class="day-card ${((new Date(`${day}T12:00:00Z`).getUTCDay()+6)%7)===i?'today':''}" style="--course:${colorOf(primary)}"><span class="eyebrow">${dayName}</span><b>${primary}</b><small>${e(courseById(primary).title)}</small><span class="day-second">รอง: ${secondary}</span><span class="day-hours">${i>=5?state.hours.weekend:state.hours.weekday} ชม.</span></div>`).join('')}</div>
 ${journeyHTML(day)}
 <div class="plan-banner"><div><span class="eyebrow">เป้าหมายทั้งหลักสูตร</span><h2>สอบครบภายใน 1/2571</h2><p>ประมาณ 2 ปีจากภาค 2/2569 · 6 ภาค รวมฤดูร้อน · สำรองถึง 2/2571</p></div><b>84 <small>หน่วยกิตในแผน</small></b></div><div class="notice">แผนนี้คาดว่าเทียบโอนได้ 42 หน่วยกิต แต่ยังไม่ถือว่าอนุมัติแล้ว ทุกภาคถัดไปต้องปรับตามวิชาเปิด คาบสอบ และผลสอบจริง ระดับหนัก/กลาง/เบากว่าเป็นการประเมินเพื่อกระจายภาระ ไม่ใช่สถิติความง่าย</div>
 <div class="section-heading"><h2>โครงสร้างวิชาที่ต้องเก็บ</h2><span class="muted">ไม่ซ้ำหมวด · 28 วิชา</span></div><div class="category-grid">${Object.entries(categoryTargets).map(([cat,target])=>`<div class="panel"><span>${categories[cat]}</span><b>${s.planned[cat]} <small>/ ${target} นก.</small></b><span class="green-text">วางแผนครบ ✓</span><small>สอบผ่านที่บันทึก ${s.passed[cat]} นก.</small></div>`).join('')}</div>
 <div class="section-heading"><h2>รายวิชาแต่ละภาค</h2><span class="muted">ย้ายวิชาอนาคตได้ตามวิชาเปิด</span></div>${s.termRows.map(t=>`<section class="term-panel panel ${t.over?'over':''}"><div class="term-title"><div><span class="term-number">${t.id===6?'เผื่อ':String(t.id+1).padStart(2,'0')}</span><div><h3>${t.name}</h3><span>${t.label} ${t.id===0?'· รายการจริง':'· แผนปรับได้'}</span></div></div><div><b>${t.credits} นก.</b><span>หนัก ${t.heavy} / กลาง ${t.courses.filter(c=>c.load==='กลาง').length} / เบากว่า ${t.courses.filter(c=>c.load==='เบากว่า').length}</span></div></div>${t.over?`<div class="notice danger">เกินเพดานวางแผน ${t.cap} หน่วยกิต ต้องลดหรือขอสิทธิตามระเบียบก่อนลงจริง</div>`:''}${t.heavy>2?'<div class="notice">วิชาที่ประเมินว่าหนักเกิน 2 วิชาในภาคนี้ ลองกระจายภาระอีกครั้ง</div>':''}${t.courses.length?`<div class="table-scroll"><table><thead><tr><th>วิชา</th><th>หมวด / ภาระ</th><th>วันสอบ</th><th>ผลสอบที่บันทึกเอง</th>${t.id?' <th>ย้ายไปภาค</th>':''}</tr></thead><tbody>${t.courses.map(c=>`<tr><td><b>${c.id}</b><div>${e(c.title)}</div><small>${e(c.reason)}</small></td><td>${e(categories[c.category])}<br>${badge(c.load,c.load==='หนัก'?'amber':'')}</td><td>${c.exam?`${thaiDate(c.exam,true)}<br>คาบ ${c.slot}`:'รอประกาศ'}</td><td><select class="grade-select" data-course="${c.id}" aria-label="ผลสอบ ${c.id}"><option value="">${c.enrolled?'ลงแล้ว / รอสอบ':'ยังไม่บันทึก'}</option>${['A','B+','B','C+','C','D+','D','F'].map(g=>`<option ${state.grades[c.id]===g?'selected':''}>${g}</option>`).join('')}</select></td>${t.id?`<td><select class="move-select" data-course="${c.id}" aria-label="ย้าย ${c.id}">${terms.filter(v=>v.id>0).map(v=>`<option value="${v.id}" ${v.id===t.id?'selected':''}>${v.name}</option>`).join('')}</select></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<p class="muted">ยังไม่มีวิชา ใช้เผื่อวิชาที่ต้องเลื่อนหรือสอบใหม่</p>'}</section>`).join('')}
 <div class="split-grid"><section class="panel"><h2>ติดตามผลที่ยืนยันแล้ว</h2><p>กรอกเฉพาะหน่วยกิตที่มหาวิทยาลัยอนุมัติ</p><label class="field">ศึกษาทั่วไปที่อนุมัติ (0–30)<input id="transfer-general" type="number" min="0" max="30" step="1" value="${state.transfer.general}"></label><label class="field">เลือกเสรีที่อนุมัติ (0–12)<input id="transfer-free" type="number" min="0" max="12" step="1" value="${state.transfer.free}"></label><button class="button secondary" data-action="save-transfer">บันทึกผลเทียบโอน</button><div class="metrics-line">เทียบโอนยืนยัน <b>${s.transfer}</b> · สอบผ่าน <b>${s.earned}</b> · ยังไม่ยืนยันครบหลักสูตร <b>${s.remaining}</b> นก.</div><p>GPA จำลองจากเกรดที่บันทึก: <b>${s.gpa===null?'ยังไม่มีข้อมูล':s.gpa.toFixed(2)}</b></p><small>ไม่รวมเทียบโอน; ไม่จำลองกฎสอบซ้ำหรือแทนเกรด ใช้ผลทางการตัดสินจบ และต้องครบหมวด + GPA ตามเกณฑ์</small></section><section class="panel"><h2>เมื่อเรียนแล้วไม่ไหว</h2><ul class="simple-list"><li>วันที่งานหนัก เลือก “1 ชม. วันยุ่ง” ที่หน้าหลัก ยังนับว่าได้เรียนต่อเนื่อง</li><li>ประเมินหลังเรียน 3–4 สัปดาห์: อ่านทันหรือไม่ และอธิบายพื้นฐานได้แค่ไหน</li><li>ลดงานอ่านเสริมก่อน แล้วกระจายวิชาหนักในภาคถัดไป</li><li>หากวิชาไม่เปิดหรือสอบชน ให้สลับวิชาในหมวดเดิม พร้อมตรวจหน่วยกิตไม่ซ้ำ</li><li>วิชาเทอมแรกลงแล้ว การเพิ่ม–ถอนต้องทำตามปฏิทินมหาวิทยาลัย</li></ul></section></div>
 <p class="quiet-note">ลำดับในแผนเป็นคำแนะนำในการปูพื้นฐาน ไม่ใช่การยืนยันวิชาบังคับก่อนตามทะเบียน · ยังไม่ยืนยันรูปแบบข้อสอบของแต่ละวิชา</p>`;}
function examPage(){const items=exams(),clashes=examClashes(items),day=today();return `${heading('EXAM CALENDAR','ตารางสอบเทอมนี้','ภาค 2/2569 · วันสอบตามรายการลงทะเบียนของคุณ · กด “แนวข้อสอบ” เพื่อฝึกทำข้อสอบแต่ละวิชา',`<button class="button secondary" data-action="calendar">${icon('download')} เพิ่มลงปฏิทิน</button>`)}<div class="exam-summary"><span class="stat-icon">${icon('check')}</span><div><b>${clashes.length?'พบคาบสอบซ้ำ':'7 วิชา · วันและคาบไม่ชนกันในรายการนี้'}</b><p>สอบระหว่าง 10–22 มีนาคม 2570 · A/B เป็นรหัสคาบ ให้ตรวจชั่วโมงสอบและห้องสอบจากตารางรายบุคคล</p></div></div><div class="exam-timeline">${items.map(c=>{const left=daysBetween(day,c.exam);return `<article class="exam-item ${left<0?'past':''}" style="--course:${colorOf(c.id)}"><div class="exam-date"><b>${Number(c.exam.slice(8))}</b><span>มี.ค. 2570</span></div><div class="exam-info"><span class="cc-code">${c.id}</span><h3>${e(c.title)}</h3><span class="muted">3 หน่วยกิต · ${left>0?`อีก ${left} วัน`:left===0?'สอบวันนี้':'สอบแล้ว'}</span></div><span class="slot">คาบ ${c.slot}</span><div class="exam-actions">${link('prep/'+c.id,`${icon('target',16)} แนวข้อสอบ${scoreText(c.id)}`,'button primary small')}${link('course/'+c.id,'บทเรียน →','button secondary small')}</div></article>`;}).join('')}</div><div class="notice">ไฟล์ปฏิทินบันทึกเป็นกิจกรรมทั้งวัน พร้อมรหัสคาบ เพื่อไม่ใส่เวลาเอง ก่อนสอบตรวจประกาศแก้ไข ตารางสอบรายบุคคล สถานที่ และอุปกรณ์ที่อนุญาตอีกครั้ง</div><div class="panel"><h3>แผนทบทวนก่อนสอบ</h3><p>ตั้งแต่ 1 ก.พ. 2570 แผนรายวันจะวนทบทวนทั้ง 7 วิชาตามลำดับวันสอบ เน้นบทที่ยังอธิบายเองไม่ได้และคำถามที่ตอบผิด โดยกันเวลาต่อเนื่องให้ POL2106 และ POL2107 ไม่รออ่านในคืนก่อนสอบ</p><p>วันที่ 21 และ 22 มีนาคมสอบติดกัน จัดสรุป POL2301 และ POL2107 ให้พร้อมก่อนเริ่มช่วงสอบ</p></div>`;}
function notes(){return notebookPage(studySpace,state);}
function about(){return `${heading('SOURCES & CONTEXT','แหล่งเรียนรู้และข้อตกลงของแผน','ข้อมูลที่ใช้สร้างห้องเรียนนี้ · อัปเดตตุลาคม 2569')}<div class="panel source-intro"><h2>อ่านบทพื้นฐาน แล้วเรียนต่อกับอาจารย์</h2><p>${e(meta.scope)} เนื้อหาแนวคิดและตัวอย่างในแอปเป็นงานเรียบเรียงใหม่ ไม่ได้คัดลอกตำราหรือถอดคำบรรยายมหาวิทยาลัย คำถามเป็นแบบฝึกของแอป ไม่ใช่ข้อสอบจริง ส่วน “เข้าใจใน 1 นาที” เป็นสรุปภาษาง่ายและชื่อแนวคิดที่ตำรารัฐศาสตร์ใช้ทั่วไป</p><p>ยังไม่ได้ตรวจความครอบคลุมกับแผนการสอนของผู้สอนภาค 2/2569 ทุกคน ให้นำหัวข้อที่อาจารย์ประกาศมาเทียบและเพิ่มบันทึกหลังเรียน โดยเฉพาะกฎหมาย กติกาสถาบัน และเหตุการณ์ร่วมสมัยที่เปลี่ยนได้</p></div><div class="source-grid">${sources.map(s=>`<article class="panel"><span class="source-icon">${icon(s.url?'link':'notes')}</span><h3>${e(s.title)}</h3><p>${e(s.detail)}</p>${s.url?`<a class="text-link" href="${e(s.url)}" target="_blank" rel="noopener noreferrer">เปิดแหล่งข้อมูล ↗</a>`:badge('หลักฐานจากผู้เรียน','green')}${s.backupUrl?`<p><a class="button secondary small" href="${e(s.backupUrl)}" target="_blank" rel="noopener noreferrer">เปิดสำเนาตารางในแอป ↗</a></p>`:''}${s.listingUrl?`<p><a class="text-link" href="${e(s.listingUrl)}" target="_blank" rel="noopener noreferrer">หน้ารวมประกาศของมหาวิทยาลัย ↗</a></p>`:''}${s.accessNote?`<p class="quiet-note">${e(s.accessNote)}</p>`:''}</article>`).join('')}</div><section class="panel context"><h2>สิ่งที่ตกลงไว้สำหรับแผนนี้</h2><ul class="simple-list"><li>เรียนปริญญาตรีใบที่สอง ใช้สิทธิเทียบโอนวุฒิจากสถาบันอื่น ฐานแผน C บริหารรัฐกิจ ส่วนกลาง</li><li>เรียนไปด้วยทำงานไปด้วย มีเวลาเรียนวันละ 1–4 ชั่วโมง แผนรายวันจึงแบ่งเป็นช่วงสั้น เลือกได้ตั้งแต่ 1 ถึง 4 ชั่วโมงในแต่ละวัน</li><li>ให้การเรียนจบเร็วและสอบผ่านเป็นเป้าหมายหลัก ไม่เลือกวิชาเพื่อนำไปประยุกต์กับงานเดิม</li><li>เป้าหมายเดิมเรื่องสอบปลัดยังเป็นบริบทระยะยาว แต่แผนนี้ไม่บังคับอ่านติวเพิ่ม และไม่คาดเดาวันเปิดสอบรอบหน้า</li><li>เทอมแรกใช้ 7 วิชาที่ลงจริงตามภาพ ไม่ใช้รายการตัวอย่างหรือรายการในแผน Excel เก่าแทน</li><li>POL2104 นับเป็นวิชาเลือกในคณะของแผน C ส่วน POL2301 และ POL2303 เป็นเอกบังคับ C</li><li>การลงข้ามกลุ่มวิชาไม่ได้ทำให้ยืนยันขั้นตอนประกาศแผนกับคณะได้ อาศัยโครงสร้างที่เรียนครบและข้อมูลทะเบียนของมหาวิทยาลัย</li><li>คาดเทียบโอน 42 นก. และวางแผนเรียน 84 นก. ผลอนุมัติรายบุคคลและการสำเร็จการศึกษาต้องใช้หลักฐานทางการ</li></ul><details><summary>ข้อมูลค่าใช้จ่ายที่เคยคุยกัน</summary><p>ภาพใบสมัครแสดงยอด 3,825 บาท และรายการเทียบโอนจากสถาบันอื่น 100 บาท ยอดในภาพไม่ใช่หลักฐานว่าจ่ายแล้ว ผลเทียบโอนและยอดคงเหลือต้องตรวจมหาวิทยาลัย ไม่แสดงว่าระบบจะคำนวณอัตโนมัติแน่นอน</p><p>ตามฐานประมาณ 42 นก. × 100 บาท = 4,200 บาท หาก 100 บาทแรกชำระและนับหักได้ จะคงเหลือประมาณ 4,100 บาท ทั้งนี้ขึ้นกับจำนวนอนุมัติจริงและการแจ้งยอดของคณะ</p></details></section>`;}
function settings(){return `${contentSettings()}${heading('YOUR STUDY DATA','ตั้งค่าและสำรองข้อมูล','ความคืบหน้า คำตอบ แฟลชการ์ด และบันทึกของคุณ')}<div class="split-grid"><section class="panel"><h2>จังหวะการเรียน</h2><label class="field">เวลาเรียนวันทำงาน (จ.–ศ.)<select id="hours-weekday">${studyHours.map(h=>`<option value="${h}" ${state.hours.weekday===h?'selected':''}>${h} ชั่วโมง</option>`).join('')}</select></label><label class="field">เวลาเรียนวันหยุด (ส.–อา.)<select id="hours-weekend">${studyHours.map(h=>`<option value="${h}" ${state.hours.weekend===h?'selected':''}>${h} ชั่วโมง</option>`).join('')}</select></label><label class="field">ขนาดตัวอักษรบทเรียน<select id="font-choice"><option value="normal" ${state.font==='normal'?'selected':''}>ปกติ</option><option value="large" ${state.font==='large'?'selected':''}>ใหญ่</option></select></label><p class="muted">วันไหนเหนื่อย เลือก 1 ชั่วโมงที่หน้าหลักได้ ไม่ต้องเร่งให้ครบ</p></section><section class="panel"><h2>ย้ายเครื่องหรือเก็บสำรอง</h2><p>โน้ต สีไฮไลต์ รูปภาพ และความคืบหน้าอยู่ใน Supabase ใช้เมนู “ข้อมูลและเปิดบนอีกเครื่อง” เพื่อคัดลอกลิงก์ส่วนตัวไปเปิดข้อมูลชุดเดียวกัน ไม่ต้องกรอกอีเมลหรือรหัสผ่าน</p><button class="button primary" data-action="export">${icon('download')} ส่งออกความคืบหน้าและบันทึกข้อความ (.json)</button><label class="import-label">นำเข้าไฟล์สำรอง<input type="file" id="import-backup" accept=".json,application/json"></label><p class="quiet-note">นำเข้าจะแทนที่ข้อมูลบัญชีนี้หลังยืนยันและส่งเข้า Supabase แนะนำส่งออกก่อนทุกครั้ง ไฟล์รองรับขนาดไม่เกิน 2 MB</p>${locked?'<button class="button secondary" data-action="recover-session">ใช้ข้อมูลของรอบนี้แทนข้อมูลเดิมที่อ่านไม่ได้</button>':''}</section></div><section class="panel"><h2>นำแผนไปใช้งาน</h2><p>ส่งออกแผนทุกภาคเป็น CSV สำหรับเปิดใน Excel และวันสอบเป็นปฏิทินได้</p><div class="button-row"><button class="button secondary" data-action="export-plan">ดาวน์โหลดแผน (.csv)</button><button class="button secondary" data-action="calendar">ดาวน์โหลดปฏิทิน (.ics)</button></div><p class="quiet-note">CSV เป็นตารางข้อมูล ไม่ใช่สมุดงาน Excel หลายชีต วันสอบอนาคตระบุ “รอประกาศ”</p></section>`;}
function contentSettings(){return `<section class="panel content-settings"><h2>เนื้อหาบทเรียนและปฏิทิน</h2><p>${contentStatus.source==='supabase'?'เชื่อมต่อ Supabase แล้ว · แก้เนื้อหาในฐานข้อมูลแล้วโหลดหน้านี้ใหม่ได้':contentStatus.source==='cache'?'กำลังใช้สำเนาข้อมูลล่าสุดที่เคยโหลดจาก Supabase':'กำลังใช้สำเนาเนื้อหาของแอป กรุณาลองโหลดข้อมูลล่าสุดอีกครั้ง'}</p><p>ข้อมูลชุดวันที่ ${thaiDate(contentStatus.catalog.updated)} · โน้ต รูปภาพ แผนส่วนตัว และความคืบหน้าเก็บใน Supabase ตามลิงก์ส่วนตัว</p><button class="button secondary" data-action="refresh-content">โหลดเนื้อหาล่าสุด</button></section>`;}
function scoreText(code){const r=prepResult(state,code);return r&&r.best!==null?` · ดีสุด ${r.best}/${r.total}`:'';}
function prepStrip(code){const g=prep[code];if(!g)return '';const r=prepResult(state,code);return `<a class="prep-strip" href="#prep/${code}" style="--course:${colorOf(code)}"><span class="stat-icon">${icon('target',22)}</span><div><b>แนวข้อสอบ ${code}</b><span>ข้อสอบเสมือน ${r.total} ข้อ แบบ 5 ตัวเลือก + รูปแบบข้อสอบ ตำรา และหัวข้อที่ควรเตรียม${r.best!==null?` · คะแนนดีสุด ${r.best}/${r.total}`:''}</span></div>${icon('arrow',18)}</a>`;}
function prepQuestion(code,q,i,p,reveal){const chosen=p.answers[i],has=Number.isInteger(chosen),show=reveal&&has;return `<li class="mock-q ${show?(chosen===q.answer?'is-right':'is-wrong'):''}" id="q-${i}"><div class="mock-num">ข้อ ${i+1}</div><h3>${e(q.prompt)}</h3><div class="choices">${q.options.map((o,v)=>`<button type="button" class="choice ${show&&v===q.answer?'correct':''} ${show&&v===chosen&&chosen!==q.answer?'incorrect':''} ${!show&&chosen===v?'picked':''}" data-action="prep-answer" data-course="${code}" data-index="${i}" data-value="${v}" aria-pressed="${chosen===v}" ${show?'disabled':''}><span>${v+1}</span>${e(o)}${show&&v===q.answer?'<b>✓</b>':''}</button>`).join('')}</div>${show?`<div class="answer-explanation ${chosen===q.answer?'correct':'incorrect'}"><strong>${chosen===q.answer?'ถูกต้อง':`ยังไม่ใช่ · คำตอบคือข้อ ${q.answer+1}`}</strong><p>${e(q.explanation)}</p>${q.lesson&&lessonById(q.lesson)?`<a class="text-link" href="#lesson/${q.lesson}">อ่านบทที่เกี่ยวข้อง →</a>`:''}</div>`:''}</li>`;}
function prepPage(code){const g=prep[code],c=courseById(code);if(!g||!c)return missing();const r=prepResult(state,code),p=state.prep[code]||{answers:{}},exam=prepMode==='exam',reveal=!exam||r.submitted,left=daysBetween(today(),c.exam),pct=r.total?Math.round(r.correct/r.total*100):0;
 const status=exam?(r.submitted?`<div class="mock-result"><b>${r.correct}/${r.total}</b><span>ได้ ${pct}% ${pct>=80?'· ยอดเยี่ยม':pct>=60?'· ใกล้แล้ว ทบทวนข้อที่ผิด':'· อ่านเฉลยแล้วทำใหม่อีกรอบ'}</span></div>`:`<div class="mock-progress">ตอบแล้ว <b>${r.answered}</b> / ${r.total} ข้อ · เปลี่ยนคำตอบได้จนกว่าจะกดส่ง</div>`):`<div class="mock-progress">ตอบแล้ว <b>${r.answered}</b> / ${r.total} · ถูก <b>${r.correct}</b> ข้อ</div>`;
 return `${link('exams','← ตารางสอบและแนวข้อสอบทุกวิชา','back-link')}<header class="course-hero" style="--course:${colorOf(code)}"><div><span class="cc-code">${code}</span><h1>แนวข้อสอบ ${e(c.title)}</h1><div class="course-facts"><span>${icon('calendar',17)} สอบ ${thaiDate(c.exam)} · คาบ ${c.slot}${left>0?` · อีก ${left} วัน`:''}</span><span>${icon('target',17)} ข้อสอบเสมือน ${r.total} ข้อ${r.best!==null?` · ดีสุด ${r.best}/${r.total}`:''}</span></div></div></header>
 <div class="prep-info"><section class="panel"><h2>${icon('notes',20)} รูปแบบข้อสอบและตำรา</h2><dl class="prep-facts"><dt>รูปแบบ</dt><dd>${e(g.format)}</dd><dt>ตำรา</dt><dd>${e(g.textbook)}</dd></dl><h3>หัวข้อที่ควรเตรียม</h3><ul class="simple-list">${g.topics.map(t=>`<li>${e(t)}</li>`).join('')}</ul></section>
 <section class="panel"><h2>${icon('search',20)} จากข้อสอบเก่าที่เผยแพร่</h2><ul class="simple-list">${g.seen.map(t=>`<li>${e(t)}</li>`).join('')}</ul><h3>เคล็ดลับวิชานี้</h3><ul class="simple-list">${g.tips.map(t=>`<li>${e(t)}</li>`).join('')}</ul><h3>หาข้อสอบเก่าจริงฝึกเพิ่ม</h3><ul class="link-list">${g.links.map(([t,u])=>`<li><a href="${e(u)}" target="_blank" rel="noopener noreferrer">${e(t)} ↗</a></li>`).join('')}</ul><p class="quiet-note">ข้อมูลรูปแบบและหัวข้อรวบรวมจากผลค้นหาร้านชีทและเว็บข้อสอบเก่า 11 ต.ค. 2569 ยังไม่ได้ยืนยันกับมหาวิทยาลัย เฉลยจากเว็บภายนอกอาจผิด (เคยพบเฉลยข้อเดียวกันต่างกันระหว่างภาค) ให้ตรวจกับตำราทุกครั้ง</p></section></div>
 <section class="mock" aria-labelledby="mock-title"><div class="mock-head"><div><h2 id="mock-title">ข้อสอบเสมือน ${r.total} ข้อ</h2><p>แต่งใหม่ตามหัวข้อที่ตำราและข้อสอบเก่ามักถาม แบบ 5 ตัวเลือกเหมือนข้อสอบราม ไม่ใช่ข้อสอบจริง</p></div><div class="segmented"><button data-action="prep-mode" data-course="${code}" data-mode="practice" class="${!exam?'active':''}">ฝึกทีละข้อ</button><button data-action="prep-mode" data-course="${code}" data-mode="exam" class="${exam?'active':''}">จำลองสอบ</button></div></div>
 <p class="mock-hint">${exam?'จำลองสอบ: เลือกคำตอบให้ครบ แล้วกด “ส่งคำตอบ” จึงจะเห็นเฉลย · แนะนำให้จับเวลาประมาณ 1 นาทีต่อข้อ':'ฝึกทีละข้อ: กดเลือกแล้วเห็นเฉลยและคำอธิบายทันที'}</p>${status}
 <ol class="mock-list">${g.questions.map((q,i)=>prepQuestion(code,q,i,p,reveal)).join('')}</ol>
 <div class="mock-actions">${exam&&!r.submitted?`<button class="button primary" data-action="prep-submit" data-course="${code}" ${r.answered?'':'disabled'}>${icon('check')} ส่งคำตอบ (${r.answered}/${r.total})</button>`:''}<button class="button secondary" data-action="prep-reset" data-course="${code}">ล้างคำตอบ ทำใหม่ทั้งชุด</button></div>${status}</section>`;}
function missing(){return `<div class="empty panel"><h1>ไม่พบหน้าที่เลือก</h1><p>เลือกบทเรียนจากรายการอีกครั้งได้เลย</p>${link('courses','ไปที่บทเรียน')}</div>`;}
function updateNav(){const active=(currentView==='lesson'||currentView==='course')?'courses':currentView==='prep'?'exams':currentView==='note'?'notes':currentView;document.querySelector('#navigation').innerHTML=navItems.map(([key,i,label])=>`<a class="nav-link ${active===key?'active':''}" href="#${key}" ${active===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${key==='courses'?`<small>${lessons.length}</small>`:''}</a>`).join('');document.querySelector('#bottom-nav').innerHTML=['home','courses','review','notes','plan','calendar'].map(key=>navItems.find(n=>n[0]===key)).map(([key,i,,short])=>`<a class="${active===key?'active':''}" href="#${key}" ${active===key?'aria-current="page"':''}>${icon(i,22)}<span>${short}</span></a>`).join('');document.querySelector('#breadcrumb').textContent=currentView==='lesson'?`${currentId.split('-')[0]} / ติวก่อนเรียน`:currentView==='prep'?`${currentId} / แนวข้อสอบ`:(navItems.find(n=>n[0]===currentView)?.[2]||{course:'ติวก่อนเรียนรายวิชา',about:'แหล่งเรียนรู้',settings:'ตั้งค่า'}[currentView]||'ห้องเรียน');}
function render(keepScroll=false){
 destroyEditor();const oldY=window.scrollY;document.documentElement.dataset.font=state.font;updateNav();
 const info=studySpace.info();
 main.innerHTML=({home,courses:courseLibrary,classroom:classroomPage,course:()=>coursePage(currentId),prep:()=>prepPage(currentId),lesson:()=>lessonPage(currentId),review,plan,calendar:calendarPage,exams:examPage,notes,note:()=>notePage(studySpace,currentId),account:()=>accountPage(studySpace),resources:()=>resourcesPage(state),about,settings}[currentView]||missing)();
 document.title=`${currentView==='lesson'?(lessonById(currentId)?.title||'บทเรียน'):document.querySelector('#breadcrumb').textContent} · RU Study Planner`;
 if(info.canEdit&&currentView==='note'&&typeof window.location!=='undefined')mountEditor(studySpace,currentId);
 if(keepScroll)window.scrollTo(0,oldY);else window.scrollTo(0,0);
}
function navigate(){const raw=location.hash.startsWith('#space=')?'home':location.hash.slice(1)||'home';const [view,id]=raw.split('/');currentView=view;currentId=id||'';reviewQueue=null;if(currentView==='lesson'&&lessonById(currentId)&&studySpace.info().canEdit){state.lastLesson=currentId;save();}render();main.focus({preventScroll:true});}
function download(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportAll(){download(`ru-study-backup-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('ส่งออกไฟล์สำรองแล้ว');}
function exportPlan(){const rows=[['ภาค','รหัส','รายวิชา','หน่วยกิต','หมวด','ภาระประมาณ','วันสอบ','คาบ','ผลสอบที่บันทึกเอง','เหตุผลลำดับเรียน'],...planSummary(state).termRows.flatMap(t=>t.courses.map(c=>[t.name,c.id,c.title,3,categories[c.category],c.load,c.exam?thaiDate(c.exam):'รอประกาศ',c.slot||'',state.grades[c.id]||'',c.reason]))];const csv='﻿'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');download('ru-study-plan-all-terms.csv',csv,'text/csv;charset=utf-8');}
function toggleBlock(id){const day=today(),list=state.planDone[day]||[];state.planDone[day]=list.includes(id)?list.filter(v=>v!==id):[...list,id];const keep=Object.keys(state.planDone).sort().slice(-120);for(const k of Object.keys(state.planDone))if(!keep.includes(k))delete state.planDone[k];save();render(true);const plan=dailyPlan(state,day);if(!list.includes(id))toast(plan.done===plan.blocks.length?'ครบแผนวันนี้แล้ว เก่งมาก ✓':'ทำเสร็จอีกหนึ่งช่วง ✓');}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action.startsWith('account-')){accountAction(action,studySpace,render,toast);return;}
 if(action.startsWith('nb-')&&!studySpace.info().canEdit){toast(studySpace.info().status);return;}
 if(action.startsWith('nb-')){notebookAction(action,b.dataset,studySpace,state,render,toast);return;}
 if(action.startsWith('cal-')){if(action==='cal-export'){download('ru-study-calendar-2-2569.ics',calendarDownload(),'text/calendar;charset=utf-8');toast('ดาวน์โหลดปฏิทินทั้งเทอมตามตัวกรองแล้ว');}else if(calendarAction(action,b.dataset))render(true);return;}
 if(action==='refresh-content'){location.reload();return;}
 if(!studySpace.info().canEdit&&!['section','mode','flip','next','prev','review-course'].includes(action)){toast('กำลังเชื่อมต่อพื้นที่บันทึก คุณอ่านบทเรียนและดูตารางได้ระหว่างรอ');return;}
 if(action==='font'){state.font=state.font==='large'?'normal':'large';save();render(true);}
 if(action==='section')document.getElementById(`section-${b.dataset.index}`)?.scrollIntoView({behavior:'smooth',block:'start'});
 if(action==='block')toggleBlock(b.dataset.id);
 if(action==='hours'){const v=Number(b.dataset.value);if(!studyHours.includes(v))return;state.todayHours={date:today(),hours:v};save();render(true);toast(`ปรับแผนวันนี้เป็น ${v} ชั่วโมงแล้ว`);}
 if(action==='prep-answer'){const code=b.dataset.course,g=prep[code],i=Number(b.dataset.index),v=Number(b.dataset.value);if(!g||!g.questions[i]||!Number.isInteger(v)||v<0||v>=g.questions[i].options.length)return;const p=state.prep[code]||(state.prep[code]={answers:{},submitted:false,best:null,last:null});if(prepMode==='exam'?p.submitted:Number.isInteger(p.answers[i]))return;p.answers[i]=v;if(prepMode==='practice'&&Object.keys(p.answers).length===g.questions.length){const r=prepResult(state,code);p.last=r.correct;p.best=Math.max(p.best??0,r.correct);toast(`ครบทุกข้อแล้ว ได้ ${r.correct}/${r.total} คะแนน`);}save();render(true);}
 if(action==='prep-submit'){const code=b.dataset.course,p=state.prep[code];if(!prep[code]||!p||p.submitted)return;p.submitted=true;const r=prepResult(state,code);p.last=r.correct;p.best=Math.max(p.best??0,r.correct);save();render(true);toast(`ได้ ${r.correct}/${r.total} คะแนน เลื่อนดูเฉลยแต่ละข้อได้เลย`);}
 if(action==='prep-reset'){const code=b.dataset.course;if(!prep[code])return;const p=state.prep[code];if(p&&Object.keys(p.answers).length&&!confirm('ล้างคำตอบชุดนี้แล้วเริ่มทำใหม่? คะแนนดีสุดยังเก็บไว้'))return;state.prep[code]={answers:{},submitted:false,best:p?.best??null,last:p?.last??null};save();render(true);document.getElementById('mock-title')?.scrollIntoView({block:'start'});}
 if(action==='prep-mode'){const code=b.dataset.course,mode=b.dataset.mode;if(!['practice','exam'].includes(mode)||mode===prepMode)return;const p=state.prep[code];if(p&&Object.keys(p.answers).length){if(!confirm('เปลี่ยนโหมดจะล้างคำตอบที่ทำค้างไว้ (คะแนนดีสุดยังเก็บไว้) ต้องการเปลี่ยนไหม?'))return;state.prep[code]={...p,answers:{},submitted:false};save();}prepMode=mode;render(true);}
 if(action==='answer'){const l=lessonById(b.dataset.lesson),i=Number(b.dataset.index),v=Number(b.dataset.value);if(!l||!l.questions[i]||v<0||v>=l.questions[i].options.length)return;state.answers[`${l.id}:${i}`]=v;save();if(reviewMode==='quiz'&&mistakesOnly&&currentView==='review'){toast(v===l.questions[i].answer?'ตอบถูกแล้ว นำออกจากข้อที่ต้องทบทวน':'บันทึกแล้ว ดูคำอธิบายเพื่อทบทวน');}render(true);}
 if(action==='retry'){for(const key of Object.keys(state.answers))if(key.startsWith(b.dataset.id+':'))delete state.answers[key];save();render(true);}
 if(action==='retry-one'){delete state.answers[b.dataset.id];save();render(true);}
 if(action==='complete'){const id=b.dataset.id;if(!lessonById(id))return;if(state.completed.includes(id)){state.completed=state.completed.filter(v=>v!==id);state.sessions=state.sessions.filter(v=>!(v.lesson===id&&v.date===today()));}else {state.completed.push(id);if(!state.sessions.some(v=>v.lesson===id&&v.date===today()))state.sessions.push({lesson:id,date:today()});}save();render(true);toast(state.completed.includes(id)?'บันทึกว่าอ่านจบแล้ว ✓ การ์ดของบทนี้เข้าคิวทบทวนแล้ว':'ยกเลิกเครื่องหมายแล้ว');}
 if(action==='mode'){reviewMode=b.dataset.mode;quizIndex=0;flipped=false;reviewQueue=null;render(true);}
 if(action==='flip'){flipped=!flipped;render(true);}
 if(action==='remember'){reviewCard(state,b.dataset.id,b.dataset.value==='yes');save();flipped=false;render(true);}
 if(action==='quiz-next'){quizIndex++;render(true);}
 if(action==='quiz-prev'){quizIndex=Math.max(0,quizIndex-1);render(true);}
 if(action==='calendar'){download('ru-exams-2-2569.ics',examICS(),'text/calendar;charset=utf-8');toast('ดาวน์โหลดปฏิทินแบบทั้งวันพร้อมรหัสคาบแล้ว');}
 if(action==='export')exportAll();
 if(action==='export-plan')exportPlan();
 if(action==='export-notes'){const text=lessons.filter(l=>state.notes[l.id]?.trim()).map(l=>`# ${l.course} — ${l.title}\n\n${state.notes[l.id]}`).join('\n\n---\n\n');download('ru-study-notes.md',text||'# ยังไม่มีบันทึก\n','text/markdown;charset=utf-8');}
 if(action==='save-transfer'){const general=Number(document.querySelector('#transfer-general').value),free=Number(document.querySelector('#transfer-free').value);if(!Number.isInteger(general)||general<0||general>30||!Number.isInteger(free)||free<0||free>12){toast('กรอกจำนวนเต็มตามช่วงที่ระบุ');return;}state.transfer={general,free};save();render(true);toast('บันทึกหน่วยกิตที่ยืนยันแล้ว');}
 if(action==='recover-session'&&confirm('ใช้ข้อมูลรอบนี้แทนข้อมูลเดิมที่อ่านไม่ได้? ควรส่งออกข้อมูลรอบนี้ก่อน')){locked=false;save();render(true);}
});
document.addEventListener('input',event=>{const el=event.target;if(!studySpace.info().canEdit&&el.id!=='lesson-search')return;if(el.id==='notebook-search'){notebookSearch(studySpace,el.value);return;}if(el.id==='lesson-search'){searchQuery=el.value;document.querySelector('#library-results').innerHTML=libraryResults();}if(el.id==='lesson-note'){state.notes[el.dataset.lesson]=el.value;const ok=save();document.querySelector('#note-status').textContent=ok?studySpace.info().status:'ยังไม่บันทึกใน Supabase กรุณาลองอีกครั้ง';}});
document.addEventListener('change',async event=>{const el=event.target;if(!studySpace.info().canEdit&&!['calendar-course','review-course','mistakes-only','include-unread'].includes(el.id))return;
 if(el.id==='notebook-course'||el.id==='notebook-source'){notebookFilter(el.value,el.id==='notebook-source'?'source':'course');render(true);return;}
 if(el.id==='notebook-import'){try{if(el.files?.[0]){await importNotebook(el.files[0],studySpace);render();}}catch(err){toast(err.message);}return;}
 if(el.id==='calendar-course'){calendarCourse(el.value);render(true);return;}
 if(el.id==='review-course'){reviewCourse=el.value;quizIndex=0;flipped=false;reviewQueue=null;render(true);}
 if(el.id==='mistakes-only'){mistakesOnly=el.checked;quizIndex=0;reviewQueue=null;render(true);}
 if(el.id==='include-unread'){includeUnread=el.checked;flipped=false;render(true);}
 if(el.classList.contains('grade-select')){if(el.value)state.grades[el.dataset.course]=el.value;else delete state.grades[el.dataset.course];save();render(true);toast('บันทึกผลที่กรอกแล้ว');}
 if(el.classList.contains('move-select')){state.termMoves[el.dataset.course]=Number(el.value);save();render(true);toast('ปรับภาคเรียนแล้ว ตรวจเพดานและวิชาเปิดก่อนลงจริง');}
 if(el.id==='hours-weekday'||el.id==='hours-weekend'){const v=Number(el.value);if(!studyHours.includes(v))return;state.hours[el.id==='hours-weekday'?'weekday':'weekend']=v;if(state.todayHours?.date===today())state.todayHours=null;save();render(true);toast('ปรับเวลาเรียนแล้ว แผนรายวันเปลี่ยนตาม');}
 if(el.id==='font-choice'){state.font=el.value;save();render(true);}
 if(el.id==='import-backup'){const file=el.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('ไฟล์เกิน 2 MB');const candidate=validateState(JSON.parse(await file.text()));if(!confirm(`นำเข้าบทที่อ่านจบ ${candidate.completed.length} บท และบันทึก ${Object.keys(candidate.notes).length} รายการ เพื่อแทนที่ข้อมูลบัญชีนี้และบันทึกเข้า Supabase?`)){el.value='';return;}state=candidate;locked=false;save();render();toast('นำเข้าข้อมูลสำเร็จ');}catch(err){toast('นำเข้าไม่สำเร็จ: '+(err.message||'รูปแบบไฟล์ไม่ถูกต้อง'));el.value='';}}
});
studySpace=createStudySpace({storage,progress:state,onProgress:value=>{state=validateState(value);locked=false;},onChange:()=>render(true),onStatus:info=>{
 if(typeof document.querySelectorAll==='function')document.querySelectorAll('[data-sync-status]').forEach(el=>el.textContent=info.status);
 const bar=document.getElementById('cloud-status-bar');if(bar){bar.dataset.phase=info.phase;bar.hidden=false;}
 for(const id of ['note-status','rich-note-status']){const el=document.getElementById(id);if(el)el.textContent=info.status;}
 storageWarning(info.cacheWarning);
 const google=document.getElementById('google-signin');if(google)google.disabled=!info.providers.google;
 const setup=document.getElementById('google-setup-note');if(setup)setup.hidden=!!info.providers.google;
 const conflict=document.getElementById('sync-conflict');if(conflict)conflict.hidden=!info.conflict;
 const last=document.getElementById('last-sync');if(last)last.textContent=info.lastSync?new Date(info.lastSync).toLocaleString('th-TH'):'ยังไม่มี';
}});
window.addEventListener('hashchange',navigate);
navigate();
export const appReady=studySpace.init();

